fn contains(list: &Vec<i32>, element: i32) -> bool {
    for &x in list.iter() {
        if x == element {
            return true;
        }
    }
    false
}

fn has_common_element(list1: &Vec<i32>, list2: &Vec<i32>) -> bool {
    // Iterate over the smaller list to reduce work.
    if list1.len() <= list2.len() {
        for &x in list1.iter() {
            if contains(list2, x) {
                return true;
            }
        }
    } else {
        for &x in list2.iter() {
            if contains(list1, x) {
                return true;
            }
        }
    }
    false
}